public struct AbsenceHistoryEntry {
    public var sessionId: String
    public var slotId: String
    public var courseId: String
    public var sessionDate: String
    public var formattedDate: String
    public var startTime: String
    public var endTime: String
    public var status: AttendanceStatus
    public var classWeight: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(sessionId: String, slotId: String, courseId: String, sessionDate: String, formattedDate: String, startTime: String, endTime: String, status: AttendanceStatus, classWeight: UInt32) {
        self.sessionId = sessionId
        self.slotId = slotId
        self.courseId = courseId
        self.sessionDate = sessionDate
        self.formattedDate = formattedDate
        self.startTime = startTime
        self.endTime = endTime
        self.status = status
        self.classWeight = classWeight
    }
}



extension AbsenceHistoryEntry: Equatable, Hashable {
    public static func ==(lhs: AbsenceHistoryEntry, rhs: AbsenceHistoryEntry) -> Bool {
        if lhs.sessionId != rhs.sessionId {
            return false
        }
        if lhs.slotId != rhs.slotId {
            return false
        }
        if lhs.courseId != rhs.courseId {
            return false
        }
        if lhs.sessionDate != rhs.sessionDate {
            return false
        }
        if lhs.formattedDate != rhs.formattedDate {
            return false
        }
        if lhs.startTime != rhs.startTime {
            return false
        }
        if lhs.endTime != rhs.endTime {
            return false
        }
        if lhs.status != rhs.status {
            return false
        }
        if lhs.classWeight != rhs.classWeight {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(sessionId)
        hasher.combine(slotId)
        hasher.combine(courseId)
        hasher.combine(sessionDate)
        hasher.combine(formattedDate)
        hasher.combine(startTime)
        hasher.combine(endTime)
        hasher.combine(status)
        hasher.combine(classWeight)
    }
}


